// Build per-item unblock context - AcmeToCasino SOAR TTL Manager
// Annotates each expired IP record with environment context
// consumed by the deployment-type switch downstream.

const results = [];

for (const item of $input.all()) {
  const row = item.json;
  results.push({ json: {
    id:               row.id,
    ip_address:       row.ip_address,
    incident_id:      row.incident_id,
    detection_type:   row.detection_type,
    severity:         row.severity,
    deployment_type:  row.deployment_type || $env.DEPLOYMENT_TYPE || 'aws',
    blocked_at:       row.blocked_at,
    expires_at:       row.expires_at,
    unblock_attempts: row.unblock_attempts || 0,
    unblock_reason:   'TTL_EXPIRED',
    unblock_timestamp: new Date().toISOString(),
    aws_waf_ipset_id:  $env.AWS_WAF_IPSET_ID || 'REPLACE_WITH_IPSET_ID',
    aws_waf_scope:     $env.AWS_WAF_SCOPE    || 'REGIONAL',
    aws_region:        $env.AWS_REGION       || 'us-east-1'
  }});
}

return results;

// AWS WAF UNBLOCK PAYLOAD BUILDER - AcmeToCasino SOAR TTL Manager
//
// The WAF UpdateIPSet API requires the current LockToken.
// In production, add a GetIPSet HTTP Request node before this one
// to retrieve the LockToken, then pass it as $json.aws_waf_lock_token.
// This node builds the DELETE (remove IP) payload.

const results = [];

for (const item of $input.all()) {
  const event = item.json;
  const ip    = event.ip_address;
  const cidr  = ip.includes('/') ? ip : `${ip}/32`;

  results.push({ json: {
    ...event,
    aws_waf_unblock_payload: {
      Name:           'AcmeToCasino-BlockList',
      Scope:          event.aws_waf_scope,
      IPSetId:        event.aws_waf_ipset_id,
      IPSetLockToken: event.aws_waf_lock_token || 'REPLACE_WITH_LOCK_TOKEN',
      Addresses:      [cidr],
      operation:      'REMOVE',
      reason: `TTL expired auto-unblock: ${event.incident_id} (blocked_at: ${event.blocked_at})`
    },
    aws_cloudwatch_unblock_metric: {
      Namespace:  'AcmeToCasino/Security',
      MetricName: 'IPAutoUnblocked',
      Value: 1,
      Unit:  'Count',
      Dimensions: [
        { Name: 'DetectionType', Value: event.detection_type },
        { Name: 'Severity',      Value: event.severity }
      ]
    }
  }});
}

return results;

// ON-PREMISE UNBLOCK COMMAND BUILDER - AcmeToCasino SOAR TTL Manager
//
// Builds iptables/nftables remove commands and cleans the blocked_ips.txt
// tracking file so the SSH node can execute them on the firewall host.

const results = [];

for (const item of $input.all()) {
  const event    = item.json;
  const ip       = event.ip_address;
  const incId    = event.incident_id;
  const useNft   = $env.USE_NFTABLES === 'true';

  let command;
  if (useNft) {
    command = `nft delete element inet filter acme_blocklist { ${ip} } 2>/dev/null || true && echo 'unblocked ${ip}'`;
  } else {
    command = [
      `iptables -D INPUT   -s ${ip} -j DROP 2>/dev/null || true`,
      `iptables -D FORWARD -s ${ip} -j DROP 2>/dev/null || true`,
      `sed -i '/^${ip.replace(/\./g, '\\.')}/d' /var/lib/acme-security/blocked_ips.txt`,
      `echo 'unblocked ${ip} ${incId}'`
    ].join(' && ');
  }

  results.push({ json: {
    ...event,
    firewall_type: useNft ? 'nftables' : 'iptables',
    ssh_unblock_command: command,
    modsecurity_delete_payload: {
      action: 'delete',
      ip: ip,
      incident_id: incId
    },
    nginx_unblock_comment: `# removed: deny ${ip}; # ${incId}`
  }});
}

return results;

// UNBLOCK RESULT ANALYSER - AcmeToCasino SOAR TTL Manager
//
// Classifies each unblock attempt as SUCCESS or FAILED.
// The HTTP response from WAF/SSH is checked for error indicators.
// Results feed into the PostgreSQL update and Slack notification.

const results = [];

for (const item of $input.all()) {
  const event  = item.json;
  const status = item.json.$response?.statusCode || item.json.status || 200;
  const body   = item.json.$response?.body || {};
  const stderr = item.json.stderr || '';

  // Consider it a failure if HTTP >= 400 or SSH stderr has 'error'
  const failed = status >= 400 || (typeof stderr === 'string' && stderr.toLowerCase().includes('error'));

  results.push({ json: {
    ip_address:        event.ip_address,
    incident_id:       event.incident_id,
    detection_type:    event.detection_type,
    severity:          event.severity,
    deployment_type:   event.deployment_type,
    unblock_status:    failed ? 'FAILED' : 'SUCCESS',
    unblock_timestamp: event.unblock_timestamp || new Date().toISOString(),
    unblock_attempts:  (event.unblock_attempts || 0) + 1,
    http_status:       status,
    error_detail:      failed ? (body.message || stderr || 'unknown error') : null,
    blocked_at:        event.blocked_at,
    expires_at:        event.expires_at,
    db_record_id:      event.id
  }});
}

return results;

